 return '''<div class="cover pipeline" aria-hidden="true"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><div class="pipeline-diagram"><span class="file-node">FASTA <b>+</b> VCF</span><span class="flow-line">↓</span><span class="core-node">G<span>Parse. Filter. Learn.</span></span><span class="flow-line">↓</span><div class="output-nodes"><span>Features</span><span>Classification</span></div></div><span class="cover-note">Pipeline illustration</span></div>'''
